            Na: () => {
                var a = _.yk('B\u1ea1n c\u00f3 th\u1ec3 xem ho\u1eb7c xo\u00e1 c\u00e1c [\ufffd#21\ufffd|\ufffd#22\ufffd]d\u1ef1 \u00e1n[\ufffd/#21\ufffd|\ufffd/#22\ufffd] c\u1ee7a m\u00ecnh b\u1ea5t c\u1ee9 l\u00fac n\u00e0o b\u1eb1ng c\u00e1ch ch\u1ecdn "Xo\u00e1 t\u1ea5t c\u1ea3 d\u1ef1 \u00e1n" trong tr\u00ecnh \u0111\u01a1n ch\u00ednh ho\u1eb7c ch\u1ecdn "Xo\u00e1" tr\u00ean m\u1ed9t D\u1ef1 \u00e1n b\u1ea5t k\u1ef3.\n    [\ufffd#21\ufffd|\ufffd#22\ufffd]L\u01b0u \u00fd r\u1eb1ng k\u1ebft qu\u1ea3 v\u00e0 phi\u00ean t\u01b0\u01a1ng t\u00e1c v\u1edbi T\u00e1c nh\u00e2n ho\u1eb7c C\u00f4ng c\u1ee5 l\u00e0 ri\u00eang bi\u1ec7t v\u00e0 c\u1ea7n \u0111\u01b0\u1ee3c xo\u00e1[\ufffd/#21\ufffd|\ufffd/#22\ufffd] ri\u00eang l\u1ebb b\u1eb1ng c\u00e1ch ch\u1ecdn tr\u00ecnh \u0111\u01a1n c\u00f3 bi\u1ec3u t\u01b0\u1ee3ng 3 d\u1ea5u ch\u1ea5m t\u01b0\u01a1ng \u1ee9ng r\u1ed3i ch\u1ecdn Xo\u00e1. Ngay c\u1ea3 sau khi b\u1ea1n xo\u00e1 d\u1eef li\u1ec7u, d\u1eef li\u1ec7u \u0111\u00f3 v\u1eabn c\u00f3 th\u1ec3 \u0111\u01b0\u1ee3c l\u01b0u v\u00e0o t\u00e0i kho\u1ea3n c\u1ee7a b\u1ea1n trong t\u1ed1i \u0111a 72 gi\u1edd. Nh\u1edd \u0111\u00f3, Google c\u00f3 th\u1ec3 cung c\u1ea5p d\u1ecbch v\u1ee5 v\u00e0 x\u1eed l\u00fd m\u1ecdi \u00fd ki\u1ebfn ph\u1ea3n h\u1ed3i. Ho\u1ea1t \u0111\u1ed9ng n\u00e0y s\u1ebd kh\u00f4ng xu\u1ea5t hi\u1ec7n trong c\u00f4ng c\u1ee5 Google Flow.');
                var b = _.yk("B\u1ea1n c\u00f3 th\u1ec3 \ufffd#27\ufffdy\u00eau c\u1ea7u[\ufffd/#27\ufffd|\ufffd/#28\ufffd] xo\u00e1 n\u1ed9i dung theo c\u00e1c ch\u00ednh s\u00e1ch c\u1ee7a ch\u00fang t\u00f4i ho\u1eb7c lu\u1eadt hi\u1ec7n h\u00e0nh. B\u1ea1n c\u0169ng c\u00f3 th\u1ec3 xu\u1ea5t th\u00f4ng tin c\u1ee7a m\u00ecnh b\u1eb1ng c\u00e1ch truy c\u1eadp v\u00e0o trang \ufffd#28\ufffdtakeout.google.com[\ufffd/#27\ufffd|\ufffd/#28\ufffd].");
                return ["Th\u00f4ng b\u00e1o n\u00e0y v\u00e0 \ufffd#5\ufffdCh\u00ednh s\u00e1ch quy\u1ec1n ri\u00eang t\u01b0\ufffd/#5\ufffd c\u1ee7a ch\u00fang t\u00f4i m\u00f4 t\u1ea3 c\u00e1ch Google x\u1eed l\u00fd d\u1eef li\u1ec7u c\u1ee7a b\u1ea1n khi b\u1ea1n t\u01b0\u01a1ng t\u00e1c v\u1edbi Google Flow. Vui l\u00f2ng \u0111\u1ecdc k\u1ef9 c\u00e1c \u0111i\u1ec1u kho\u1ea3n n\u00e0y.", "Khi b\u1ea1n d\u00f9ng Google Flow, Google s\u1ebd thu th\u1eadp d\u1eef li\u1ec7u v\u1ec1 c\u00e1c ho\u1ea1t \u0111\u1ed9ng t\u01b0\u01a1ng t\u00e1c c\u1ee7a b\u1ea1n v\u1edbi Google Flow, n\u1ed9i dung b\u1ea1n t\u1ea3i l\u00ean, k\u1ebft qu\u1ea3 \u0111\u01b0\u1ee3c t\u1ea1o, th\u00f4ng tin v\u1ec1 vi\u1ec7c s\u1eed d\u1ee5ng t\u00ednh n\u0103ng li\u00ean quan v\u00e0 \u00fd ki\u1ebfn ph\u1ea3n h\u1ed3i c\u1ee7a b\u1ea1n. Google s\u1eed d\u1ee5ng d\u1eef li\u1ec7u n\u00e0y theo \ufffd#8\ufffdCh\u00ednh s\u00e1ch quy\u1ec1n ri\u00eang t\u01b0\ufffd/#8\ufffd c\u1ee7a ch\u00fang t\u00f4i nh\u1eb1m cung c\u1ea5p, c\u1ea3i thi\u1ec7n v\u00e0 ph\u00e1t tri\u1ec3n c\u00e1c s\u1ea3n ph\u1ea9m, d\u1ecbch v\u1ee5 c\u0169ng nh\u01b0 c\u00f4ng ngh\u1ec7 h\u1ecdc m\u00e1y c\u1ee7a Google. Theo m\u1eb7c \u0111\u1ecbnh, Google s\u1ebd l\u01b0u tr\u1eef c\u00e1c c\u00e2u l\u1ec7nh, n\u1ed9i dung b\u1ea1n t\u1ea3i l\u00ean, d\u1ef1 \u00e1n, k\u1ebft qu\u1ea3 \u0111\u01b0\u1ee3c t\u1ea1o (k\u1ec3 c\u1ea3 h\u00ecnh \u1ea3nh, video v\u00e0 c\u00f4ng c\u1ee5) c\u0169ng nh\u01b0 si\u00eau d\u1eef li\u1ec7u c\u00f3 li\u00ean quan cho \u0111\u1ebfn khi b\u1ea1n xo\u00e1 ch\u00fang. Theo m\u1eb7c \u0111\u1ecbnh, Google s\u1ebd l\u01b0u tr\u1eef c\u00e1c phi\u00ean t\u01b0\u01a1ng t\u00e1c c\u1ee7a b\u1ea1n v\u1edbi T\u00e1c nh\u00e2n v\u00e0 C\u00f4ng c\u1ee5 trong 18 th\u00e1ng.", "\u0110\u1ec3 gi\u00fap n\u00e2ng cao ch\u1ea5t l\u01b0\u1ee3ng v\u00e0 c\u1ea3i thi\u1ec7n c\u00e1c s\u1ea3n ph\u1ea9m c\u1ee7a ch\u00fang t\u00f4i, nh\u00e2n vi\u00ean \u0111\u00e1nh gi\u00e1 s\u1ebd \u0111\u1ecdc, ch\u00fa th\u00edch v\u00e0 x\u1eed l\u00fd m\u1ed9t m\u1eabu d\u1eef li\u1ec7u c\u1ee7a b\u1ea1n. Ch\u00fang t\u00f4i th\u1ef1c hi\u1ec7n nhi\u1ec1u bi\u1ec7n ph\u00e1p \u0111\u1ec3 b\u1ea3o v\u1ec7 quy\u1ec1n ri\u00eang t\u01b0 c\u1ee7a b\u1ea1n trong qu\u00e1 tr\u00ecnh n\u00e0y, k\u1ec3 c\u1ea3 vi\u1ec7c t\u00e1ch c\u00e1c n\u1ed9i dung b\u1ea1n t\u1ea3i l\u00ean v\u00e0 k\u1ebft qu\u1ea3 do c\u00f4ng c\u1ee5 t\u1ea1o kh\u1ecfi T\u00e0i kho\u1ea3n Google c\u1ee7a b\u1ea1n tr\u01b0\u1edbc khi nh\u00e2n vi\u00ean \u0111\u00e1nh gi\u00e1 xem ho\u1eb7c ch\u00fa th\u00edch ch\u00fang.\n    \ufffd#11\ufffdVui l\u00f2ng kh\u00f4ng g\u1eedi th\u00f4ng tin m\u1eadt ho\u1eb7c b\u1ea5t k\u1ef3 d\u1eef li\u1ec7u n\u00e0o m\u00e0 b\u1ea1n kh\u00f4ng mu\u1ed1n nh\u00e2n vi\u00ean \u0111\u00e1nh gi\u00e1 xem ho\u1eb7c kh\u00f4ng mu\u1ed1n Google s\u1eed d\u1ee5ng \u0111\u1ec3 c\u1ea3i thi\u1ec7n c\u00e1c s\u1ea3n ph\u1ea9m, d\u1ecbch v\u1ee5 v\u00e0 c\u00f4ng ngh\u1ec7 h\u1ecdc m\u00e1y c\u1ee7a ch\u00fang t\u00f4i.\ufffd/#11\ufffd", 'N\u1ebfu mu\u1ed1n s\u1eed d\u1ee5ng Google Flow m\u00e0 kh\u00f4ng mu\u1ed1n d\u1eef li\u1ec7u c\u1ee7a m\u00ecnh \u0111\u01b0\u1ee3c d\u00f9ng \u0111\u1ec3 n\u00e2ng cao ch\u1ea5t l\u01b0\u1ee3ng v\u00e0 c\u1ea3i thi\u1ec7n c\u00e1c s\u1ea3n ph\u1ea9m c\u1ee7a ch\u00fang t\u00f4i, b\u1ea1n c\u00f3 th\u1ec3 t\u1eaft tu\u1ef3 ch\u1ecdn "Gi\u00fap c\u1ea3i thi\u1ec7n Flow" trong tr\u00ecnh \u0111\u01a1n ch\u00ednh.', 'Nh\u1eefng cu\u1ed9c tr\u00f2 chuy\u1ec7n \u0111\u00e3 \u0111\u01b0\u1ee3c nh\u00e2n vi\u00ean \u0111\u00e1nh gi\u00e1 xem x\u00e9t ho\u1eb7c ch\u00fa th\u00edch (v\u00e0 d\u1eef li\u1ec7u li\u00ean quan nh\u01b0 ng\u00f4n ng\u1eef ho\u1eb7c \u00fd ki\u1ebfn ph\u1ea3n h\u1ed3i c\u1ee7a b\u1ea1n) s\u1ebd kh\u00f4ng b\u1ecb xo\u00e1 khi b\u1ea1n xo\u00e1 d\u1eef li\u1ec7u ho\u1eb7c t\u1eaft tu\u1ef3 ch\u1ecdn "Gi\u00fap c\u1ea3i thi\u1ec7n Flow" v\u00ec ch\u00fang \u0111\u01b0\u1ee3c l\u01b0u tr\u1eef ri\u00eang bi\u1ec7t v\u00e0 kh\u00f4ng li\u00ean k\u1ebft v\u1edbi T\u00e0i kho\u1ea3n Google c\u1ee7a b\u1ea1n. Thay v\u00e0o \u0111\u00f3, nh\u1eefng cu\u1ed9c tr\u00f2 chuy\u1ec7n n\u00e0y s\u1ebd \u0111\u01b0\u1ee3c l\u01b0u gi\u1eef trong t\u1ed1i \u0111a 18 th\u00e1ng.', a, "N\u1ebfu b\u1ea1n xo\u00e1 d\u1eef li\u1ec7u c\u1ee7a m\u00ecnh tr\u00ean Google Flow, c\u00e1c ch\u1ebf \u0111\u1ed9 c\u00e0i \u0111\u1eb7t kh\u00e1c c\u00f3 th\u1ec3 ti\u1ebfp t\u1ee5c l\u01b0u d\u1eef li\u1ec7u trong qu\u00e1 tr\u00ecnh b\u1ea1n s\u1eed d\u1ee5ng nh\u1eefng d\u1ecbch v\u1ee5 kh\u00e1c c\u1ee7a Google.", b, "H\u00e3y truy c\u1eadp v\u00e0o \ufffd#31\ufffdTrung t\u00e2m tr\u01a1\u0323 giu\u0301p v\u1ec1 Google Flow\ufffd/#31\ufffd \u0111\u1ec3 t\u00ecm hi\u1ec3u th\u00eam.", "Google Flow \u0111ang kh\u00f4ng ng\u1eebng ph\u00e1t tri\u1ec3n v\u00e0 c\u00f3 th\u1ec3 t\u1ea1o ra th\u00f4ng tin kh\u00f4ng ch\u00ednh x\u00e1c ho\u1eb7c ph\u1ea3n c\u1ea3m (k\u1ec3 c\u1ea3 th\u00f4ng tin v\u1ec1 con ng\u01b0\u1eddi). Nh\u1eefng th\u00f4ng tin n\u00e0y kh\u00f4ng th\u1ec3 hi\u1ec7n quan \u0111i\u1ec3m c\u1ee7a Google. H\u00e3y x\u00e1c minh c\u00e1c c\u00e2u tr\u1ea3 l\u1eddi.", "\u0110\u1eebng coi c\u00e2u tr\u1ea3 l\u1eddi c\u1ee7a Google Flow l\u00e0 th\u00f4ng tin ch\u1ea9n \u0111o\u00e1n, \u0111i\u1ec1u tr\u1ecb ho\u1eb7c l\u1eddi khuy\u00ean v\u1ec1 y t\u1ebf, ph\u00e1p l\u00fd, t\u00e0i ch\u00ednh hay chuy\u00ean m\u00f4n kh\u00e1c.", 'B\u1ea1n c\u00f3 th\u1ec3 g\u1eedi \u00fd ki\u1ebfn ph\u1ea3n h\u1ed3i b\u1ea5t c\u1ee9 l\u00fac n\u00e0o b\u1eb1ng c\u00e1ch ch\u1ecdn tr\u00ecnh \u0111\u01a1n c\u00f3 bi\u1ec3u t\u01b0\u1ee3ng ba d\u1ea5u ch\u1ea5m b\u00ean c\u1ea1nh m\u1ed9t k\u1ebft qu\u1ea3 b\u1ea5t k\u1ef3 r\u1ed3i ch\u1ecdn "G\u1eafn c\u1edd cho k\u1ebft qu\u1ea3".', "D\u1eef li\u1ec7u c\u1ee7a b\u1ea1n v\u00e0 Google Flow", "D\u1eef li\u1ec7u c\u1ee7a b\u1ea1n v\u00e0 Google Flow", "Thi\u1ebft l\u1eadp ch\u1ebf \u0111\u1ed9 c\u00e0i \u0111\u1eb7t c\u1ee7a b\u1ea1n", "Thi\u1ebft l\u1eadp ch\u1ebf \u0111\u1ed9 c\u00e0i \u0111\u1eb7t c\u1ee7a b\u1ea1n", "\u0110i\u1ec1u c\u1ea7n bi\u1ebft", "\u0110i\u1ec1u c\u1ea7n bi\u1ebft", [1, "privacy-section"], ["target", "_blank", "rel", "noopener noreferrer", 3, "href"], "href;https://support.google.com/legal/answer/3110420?visit_id=637939486089565735-343938859;target;_blank;rel;noopener noreferrer".split(";"), "href;https://takeout.google.com;target;_blank;rel;noopener noreferrer".split(";"), "href;https://support.google.com/flow#topic=16908930;target;_blank;rel;noopener noreferrer".split(";")]
            }
